// filepath: directory_lister.js
// action: CREATE
function listFiles(dir) {
  const fs = require('fs');
  const path = require('path');

  if (!dir) {
    console.error('Usage: node directory_lister.js <directory>');
    process.exit(1);
  }

  const files = [];
  function walk(currentDirPath) {
    fs.readdirSync(currentDirPath).forEach(file => {
      const filePath = path.join(currentDirPath, file);
      if (fs.statSync(filePath).isDirectory()) {
        walk(filePath);
      } else {
        files.push(path.relative(dir, filePath));
      }
    });
  }

  walk(dir);

  files.sort((a, b) => a.localeCompare(b));

  for (const file of files) {
    console.log(file);
  }
}
